n":0,"max":12,"step":1,"chart":true,"aggregate":"sum"},{"id":"hits","type":"number","label":"Coups sûrs","min":0,"max":10,"step":1,"chart":true,"aggregate":"sum"},{"id":"runs","type":"number","label":"Points marqués","min":0,"max":20,"step":1,"chart":true,"aggregate":"sum"}],"ultimate":[{"id":"minutes_played","type":"number","label":"Temps joué","min":0,"max":120,"step":1,"chart":true,"aggregate":"sum","unit":"min"},{"id":"points_scored","type":"number","label":"Points marqués","min":0,"max":30,"step":1,"chart":true,"aggregate":"sum"},{"id":"assists","type":"number","label":"Passes décisives","min":0,"max":30,"step":1,"chart":true,"aggregate":"sum"}],"water_polo":[{"id":"minutes_played","type":"number","label":"Temps joué","min":0,"max":48,"step":1,"chart":true,"aggregate":"sum","unit":"min"},{"id":"goals","type":"number","label":"Buts","min":0,"max":20,"step":1,"chart":true,"aggregate":"sum"},{"id":"assists","type":"number","label":"Passes décisives","min":0,"max":20,"step":1,"chart":true,"aggregate":"sum"}]}'::jsonb) loop
    select s.extra_fields into v_old from public.sports s where s.id = r.sport and s.is_active;
    if not found then continue; end if;
    v_old := coalesce(v_old, '[]'::jsonb);
    if jsonb_typeof(v_old) <> 'array' then continue; end if;
    if (v_old -> 0 ->> 'id') = (r.fields -> 0 ->> 'id') then continue; end if;
    v_n := jsonb_array_length(r.fields);
    select jsonb_agg(f.value || jsonb_build_object('priority', f.ord) order by f.ord) into v_new
      from jsonb_array_elements(r.fields) with ordinality f(value, ord);
    select coalesce(jsonb_agg(o.value || jsonb_build_object('priority', v_n + o.ord) order by o.ord), '[]'::jsonb) into v_rest
      from jsonb_array_elements(v_old) with ordinality o(value, ord)
      where not exists (select 1 from jsonb_array_elements(v_new) x where x ->> 'id' = o.value ->> 'id');
    update public.sports set extra_fields = v_new || v_rest where id = r.sport;
    v_done := v_done + 1;
  end loop;
  raise notice 'sport measures updated for % sports', v_done;
end $$;
